"""Read-only archive of public transitions generated by an external actor.

This class has NO action-probing method, simulator access, or environment
control. An independent synthetic actor chooses actions in the BENCHMARK.
Observer-initiated harm is counted separately: passive for the learner
does not mean harm-free data collection or valid causal inference.
"""
from __future__ import annotations

import json

from developmental_ai.observable_affordances import (
    NumericOutcomeMemory, check, outcome, canonical, digest
)

SCHEMA="developmental-ai.passive-public-outcomes/v1"
MAX_EVENTS=240
MIN_NEIGHBORS=5
MIN_PROGRESS=0.6
MAX_PREDICTED_DAMAGE=0.0


class PassiveOutcomeArchive:
    def __init__(self):
        self.events=[]
        self._episodes=set()

    def observe(self,before,action,after):
        """Record an action that ALREADY happened; never initiate one."""
        check(before);check(after)
        if (before["tick"]!=0 or after["tick"]!=1
            or len(self.events)>=MAX_EVENTS
            or before["episode"] in self._episodes):
            raise ValueError("duplicate, noninitial or oversized passive observation")
        public_event=outcome(before,action,after)
        # Strong transition shape check, including after.done=True frames.
        if (before["sensors"]!=[0,0] or
            (not after["done"] and
             {r["id"] for r in after["actions"]} !=
             {r["id"] for r in before["actions"]}-{action})):
            raise ValueError("inconsistent public actor trace")
        self.events.append({
            "before":json.loads(canonical(before)),
            "action":action,
            "after":json.loads(canonical(after)),
            "outcome":json.loads(canonical(public_event)),
        })
        self._episodes.add(before["episode"])
        return public_event

    def memory(self):
        if not self.events:
            raise ValueError("no externally generated public evidence")
        result=NumericOutcomeMemory()
        for row in self.events:
            result.add(row["outcome"])
        return result

    def guarded_choose(self,frame):
        """Optional, conservative candidate, built ONLY from observed data.

        A zero kNN damage estimate is NOT a bound on real-world risk.
        The selector may abstain and has no authority outside simulation.
        """
        check(frame)
        if frame["done"]:
            return None
        memory=self.memory()
        ranked=[]
        for row in frame["actions"]:
            estimate=memory.estimate(row["features"])
            if (estimate["evidence"]<MIN_NEIGHBORS
                or estimate["progress"]<MIN_PROGRESS
                or estimate["damage"]>MAX_PREDICTED_DAMAGE):
                continue
            ranked.append((-estimate["progress"],row["id"]))
        return min(ranked)[1] if ranked else None

    def stats(self):
        return {"observations":len(self.events),
                "actor_harmful_actions":sum(int(x["outcome"]["damage"]) for x in self.events),
                "actor_productive_actions":sum(int(x["outcome"]["progress"]) for x in self.events),
                "actor_neutral_actions":sum(int(not x["outcome"]["progress"] and
                                                 not x["outcome"]["damage"]) for x in self.events),
                "learner_generated_training_actions":0}

    def record(self):
        if not self.events:
            raise ValueError("no observations to checkpoint")
        state={"schema":SCHEMA,"events":self.events}
        return {"state":json.loads(canonical(state)),"sha256":digest(state)}

    @classmethod
    def restore(cls,saved):
        if (type(saved) is not dict or set(saved)!={"state","sha256"}
            or type(saved["state"]) is not dict
            or saved["sha256"]!=digest(saved["state"])):
            raise ValueError("invalid passive checkpoint digest")
        state=saved["state"]
        if (set(state)!={"schema","events"}
            or state["schema"]!=SCHEMA
            or type(state["events"]) is not list
            or not 1<=len(state["events"])<=MAX_EVENTS):
            raise ValueError("invalid passive checkpoint schema")
        archive=cls()
        for row in state["events"]:
            if type(row) is not dict or set(row)!={"before","action","after","outcome"}:
                raise ValueError("invalid passive public event")
            replayed=archive.observe(row["before"],row["action"],row["after"])
            if replayed!=row["outcome"]:
                raise ValueError("recorded outcome is not supported by public sensors")
        if archive.record()!=saved:
            raise ValueError("passive evidence could not be replayed")
        return archive
